<script setup lang="ts">import { computed,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { Clock } from '@element-plus/icons-vue';const submitted=ref(false);const answers=reactive<Record<string,string>>({});const questions=[{id:'q1',stem:'跨境电商清单申报前，哪组数据需要保持一致？',options:['订单、支付、物流数据','商品图片、客服昵称、浏览记录','推荐结果、搜索排序、缓存键']},{id:'q2',stem:'以下哪项可以作为订单交易事实来源？',options:['Elasticsearch 索引','Redis 缓存','订单服务数据库']},{id:'q3',stem:'命中人工审核后，正确处理方式是？',options:['跳过审核直接放行','按回执补充材料并保留版本与操作记录','让 AI 自动修改申报数据']}];const answered=computed(()=>Object.keys(answers).length);function submit(){if(answered.value<questions.length)return ElMessage.warning('请完成全部题目');submitted.value=true};</script>
<template><div class="quiz-page"><header><div><span>岗位闯关</span><b class="serif">清单申报与海关审核</b></div><div><el-icon><Clock/></el-icon>剩余 14:36</div></header><main><section class="quiz-card paper-card"><div class="quiz-meta"><span>共 {{questions.length}} 题 · 满分 100 · 80 分通过</span><el-progress :percentage="answered/questions.length*100" :show-text="false"/></div><article v-for="(q,i) in questions" :key="q.id"><h2><span>{{i+1}}</span>{{q.stem}}</h2><el-radio-group v-model="answers[q.id]" class="options"><el-radio v-for="(o,j) in q.options" :key="o" :value="o" border><i>{{String.fromCharCode(65+j)}}</i>{{o}}</el-radio></el-radio-group></article><el-button type="primary" size="large" @click="submit">提交答案</el-button></section></main><el-dialog v-model="submitted" title="闯关结果" width="460" :close-on-click-modal="false"><div class="result"><div class="score serif">92<small>分</small></div><h2 class="serif">恭喜通过本章闯关</h2><p>答对 3 题，下一章节已由服务端解锁。</p><el-progress :percentage="92" status="success"/></div><template #footer><el-button @click="$router.push('/workspace/training/progress')">查看学习档案</el-button><el-button type="primary" @click="$router.push('/workspace/training/courses/c1')">返回课程</el-button></template></el-dialog></div></template>
<style scoped>.quiz-page{min-height:100vh;background:#edf0eb}.quiz-page>header{height:70px;display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,calc((100% - 900px)/2));background:#0a403c;color:#fff}.quiz-page>header span,.quiz-page>header b{display:block}.quiz-page>header span{color:#d3b86f;font-size:10px;letter-spacing:.15em}.quiz-page>header b{margin-top:4px}.quiz-page>header>div:last-child{display:flex;align-items:center;gap:7px;color:#b4c9c3}.quiz-page main{padding:30px 20px}.quiz-card{max-width:900px;margin:0 auto;padding:30px 40px}.quiz-meta{display:grid;grid-template-columns:1fr 260px;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--line);color:var(--muted);font-size:12px}.quiz-card article{padding:24px 0;border-bottom:1px solid var(--line)}.quiz-card h2{display:flex;gap:10px;font-size:17px}.quiz-card h2 span{display:grid;place-items:center;flex:0 0 28px;height:28px;background:var(--jade);color:white;font-size:13px}.options{width:100%;display:grid;gap:9px;padding-left:38px}.options .el-radio{height:auto;margin:0;padding:12px}.options i{display:inline-grid;place-items:center;width:23px;height:23px;margin-right:10px;background:#edf1ed;font-style:normal}.quiz-card>.el-button{display:block;margin:25px auto 0;min-width:160px}.result{text-align:center}.score{color:#2b8d68;font-size:68px}.score small{font-size:18px}.result p{color:var(--muted)}@media(max-width:600px){.quiz-card{padding:22px 16px}.quiz-meta{grid-template-columns:1fr}.options{padding-left:0}}</style>
